 "prior_work": {
  "already_answered": "no",
  "cited": ["FAM:SF-APPS-088", "FAM:SF-APPS-075", "FAM:SF-APPS-078", "FAM:SF-APPA-005"],
  "summary": "No retrieved record tests offensive reorganization relative to L against change in PPP. The closest work is FAM:SF-APPS-088 (identity displacement after connector absence, supported, n=96 matched pairs). FAM:SF-APPS-075 and FAM:SF-APPS-078 are descriptive PPP and volume analyses, and FAM:SF-APPA-005 is untestable under inferred labels. These support the design but do not answer the question."
 },
 "risks": [
  {"code": "OUTCOME_DERIVED_LABEL", "text": "Reorganization and PPP change may share possession-level inputs, making the association partly definitional."},
  {"code": "LABEL_ERROR", "text": "Play-type or initiator labels may be inferred and noisy (cf. FAM:SF-APPA-005)."},
  {"code": "MEASURE_RELIABILITY", "text": "The reorganization metric has no recorded reliability check across seasons or teams."},
  {"code": "SAMPLE_SIZE_POWER", "text": "n=148 spells gives limited power for a modest correlation (about rho ≈ 0.23)."},
  {"code": "EXPOSURE_SPARSITY", "text": "Absences of key organizers are rare, so per-player or per-role subgroups may be very small."},
  {"code": "RTM_SELECTION", "text": "Absences that cause reorganization may be selected on prior performance or injury status (regression to the mean in PPP)."},
  {"code": "CONFOUNDING", "text": "Opponent quality, minutes, and usage are likely confounders of both reorganization and PPP change."},
  {"code": "LEAKAGE_LOOKAHEAD", "text": "L must be computed only from pre-absence data; post-absence data in the baseline would leak."},
  {"code": "MECHANICAL_FLOOR", "text": "Absence of a high-usage player forces reorganization, so a positive association may be mechanical (cf. FAM:SF-APPS-088)."},
  {"code": "MULTIPLE_TESTING", "text": "Several reorganization definitions or windows would inflate false positives without correction."},
  {"code": "DRIFT_NONSTATIONARITY", "text": "Partial 2025-26 data and rule or pace drift across 2022-23 to 2025-26 may change PPP baselines."},
  {"code": "PLACEBO_DEPENDENCE", "text": "No placebo or falsification test is specified, so an effect may be produced by the design."}
 ],
 "predicted_outcome": {
  "supported": 0.15,
  "rejected": 0.2,
  "untestable": 0.3,
  "artifact": 0.1,
  "uncertain": 0.25
 },
 "decision": "proceed_with_changes",
